package mx.com.mesaregia.logistica.api.controller; import jakarta.validation.Valid; import mx.com.mesaregia.logistica.api.request.ToleranciaUpdateRequest; import mx.com.mesaregia.logistica.api.response.ToleranciaResponse; import mx.com.mesaregia.logistica.application.service.ToleranciaService; import mx.com.mesaregia.logistica.domain.enums.CodigoEtapa; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List; @RestController @RequestMapping("/api/v1/logistica/tolerancias") @PreAuthorize("hasAuthority('logistica.tolerancias.gestionar')") public class ToleranciaController {private final ToleranciaService s;public ToleranciaController(ToleranciaService s){this.s=s;} @GetMapping public List<ToleranciaResponse> listar(){return s.listar();} @PutMapping("/{codigo}") public ToleranciaResponse actualizar(@PathVariable CodigoEtapa codigo,@Valid @RequestBody ToleranciaUpdateRequest r){return s.actualizar(codigo,r);} }
